/// Hit flash: the sprite mixed toward a flat colour, alpha kept. Tween amount 1 -> 0 on a hit.
#[derive(Clone, Copy, Debug, ShaderType)]
pub struct FlashParams {
    pub amount: f32,
    pub flash_color: Vec3,
    pub canvas: Vec2,
    pub texel: Vec2,
}

impl Default for FlashParams {
    fn default() -> Self {
        Self {
            amount: 0.6,
            flash_color: Vec3::new(1.0, 1.0, 1.0),
            canvas: Vec2::new(64.0, 64.0),
            texel: Vec2::new(0.03125, 0.03125),
        }
    }
}

#[derive(Asset, TypePath, AsBindGroup, Clone, Debug)]
pub struct FlashMaterial {
    #[uniform(0)]
    pub params: FlashParams,
    #[texture(1)]
    #[sampler(2)]
    pub main: Handle<Image>,
}

impl Material2d for FlashMaterial {
    fn fragment_shader() -> ShaderRef {
        "shaders/kit/flash.wesl".into()
    }

    fn alpha_mode(&self) -> AlphaMode2d {
        AlphaMode2d::Blend
    }
}

