/// Registers every recipe's material.
pub struct KitShadersPlugin;

impl Plugin for KitShadersPlugin {
    fn build(&self, app: &mut App) {
        app.add_plugins(Material2dPlugin::<FlashMaterial>::default());
        app.add_plugins(Material2dPlugin::<DissolveMaterial>::default());
        app.add_plugins(Material2dPlugin::<OutlineMaterial>::default());
        app.add_plugins(Material2dPlugin::<PaletteSwapMaterial>::default());
        app.add_plugins(Material2dPlugin::<ColorblindMaterial>::default());
        app.add_plugins(Material2dPlugin::<CrtMaterial>::default());
        app.add_plugins(Material2dPlugin::<VignetteMaterial>::default());
        app.add_plugins(Material2dPlugin::<ToonRimMaterial>::default());
        app.add_plugins(Material2dPlugin::<ScrollWaterMaterial>::default());
        app.add_plugins(Material2dPlugin::<TriplanarMaterial>::default());
        app.add_plugins(Material2dPlugin::<SpriteLightMaterial>::default());
    }
}

/// Spawn `bundle` with recipe `name`'s material at its default parameters. False for an unknown name.
pub fn spawn_recipe(world: &mut World, name: &str, main: Handle<Image>, aux: Option<Handle<Image>>,
                    bundle: impl Bundle) -> bool {
    match name {
        "flash" => {
            let m = world.resource_mut::<Assets<FlashMaterial>>()
                .add(FlashMaterial { params: FlashParams::default(), main, });
            world.spawn((bundle, MeshMaterial2d(m)));
        }
        "dissolve" => {
            let m = world.resource_mut::<Assets<DissolveMaterial>>()
                .add(DissolveMaterial { params: DissolveParams::default(), main, aux: aux.unwrap_or_default(), });
            world.spawn((bundle, MeshMaterial2d(m)));
        }
        "outline" => {
            let m = world.resource_mut::<Assets<OutlineMaterial>>()
                .add(OutlineMaterial { params: OutlineParams::default(), main, });
            world.spawn((bundle, MeshMaterial2d(m)));
        }
        "palette_swap" => {
            let m = world.resource_mut::<Assets<PaletteSwapMaterial>>()
                .add(PaletteSwapMaterial { params: PaletteSwapParams::default(), main, aux: aux.unwrap_or_default(), });
            world.spawn((bundle, MeshMaterial2d(m)));
        }
        "colorblind" => {
            let m = world.resource_mut::<Assets<ColorblindMaterial>>()
                .add(ColorblindMaterial { params: ColorblindParams::default(), main, });
            world.spawn((bundle, MeshMaterial2d(m)));
        }
        "crt" => {
            let m = world.resource_mut::<Assets<CrtMaterial>>()
                .add(CrtMaterial { params: CrtParams::default(), main, });
            world.spawn((bundle, MeshMaterial2d(m)));
        }
        "vignette" => {
            let m = world.resource_mut::<Assets<VignetteMaterial>>()
                .add(VignetteMaterial { params: VignetteParams::default(), main, });
            world.spawn((bundle, MeshMaterial2d(m)));
        }
        "toon_rim" => {
            let m = world.resource_mut::<Assets<ToonRimMaterial>>()
                .add(ToonRimMaterial { params: ToonRimParams::default(), main, });
            world.spawn((bundle, MeshMaterial2d(m)));
        }
        "scroll_water" => {
            let m = world.resource_mut::<Assets<ScrollWaterMaterial>>()
                .add(ScrollWaterMaterial { params: ScrollWaterParams::default(), main, });
            world.spawn((bundle, MeshMaterial2d(m)));
        }
        "triplanar" => {
            let m = world.resource_mut::<Assets<TriplanarMaterial>>()
                .add(TriplanarMaterial { params: TriplanarParams::default(), main, aux: aux.unwrap_or_default(), });
            world.spawn((bundle, MeshMaterial2d(m)));
        }
        "sprite_light" => {
            let m = world.resource_mut::<Assets<SpriteLightMaterial>>()
                .add(SpriteLightMaterial { params: SpriteLightParams::default(), main, aux: aux.unwrap_or_default(), });
            world.spawn((bundle, MeshMaterial2d(m)));
        }
        _ => return false,
    }
    true
}
